889	/// Note: Folding must be associative, i.e. any implementation must satisfy
890	/// `fold(fold(a, b), c) == fold(a, fold(b, c))`.
891	pub trait Fold {
892	    /// Fold this inner value with an outer folded value.
893	    fn fold(self, outer: Self) -> Self;
