1053	    /// Panics if no rule exists for this target-element combination.
1054	    #[track_caller]
1055	    pub fn replace<T: NativeElement>(&mut self, target: Target, f: ShowFn<T>) {
1056	        let res = self.rules.insert((T::ELEM, target), NativeShowRule::new(f));
1057	        if res.is_none() {
1058	            panic!(
